package com.bank.merge;

import java.util.PriorityQueue;
import java.util.logging.Logger;

// Merges K timestamp-sorted settlement streams into one sorted stream.
public class SettlementMerger {

    private static final Logger log = Logger.getLogger(SettlementMerger.class.getName());

    public ListNode merge(ListNode[] lists) {
        PriorityQueue<ListNode> heap =
                new PriorityQueue<>((a, b) -> Long.compare(a.timestamp, b.timestamp));
        for (ListNode l : lists) {
            if (l != null) heap.offer(l); // seed with each stream's head
        }

        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        while (!heap.isEmpty()) {
            ListNode n = heap.poll();      // global earliest front
            tail.next = n;
            tail = n;
            if (n.next != null) {
                heap.offer(n.next);        // advance that stream
            }
        }
        log.info("Merged K streams into one sorted stream");
        return dummy.next;
    }
}
