package com.bank.merge;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class MergeDemo {

    private static final Logger log = Logger.getLogger(MergeDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    private static ListNode build(long... ts) {
        ListNode dummy = new ListNode(0), t = dummy;
        for (long v : ts) { t.next = new ListNode(v); t = t.next; }
        return dummy.next;
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Merge K Settlement Streams");
        ListNode[] streams = {
            build(100, 400, 700),  // region A
            build(200, 500, 800),  // region B
            build(150, 300, 900)   // region C
        };
        SettlementMerger merger = new SettlementMerger();
        ListNode merged = merger.merge(streams);

        StringBuilder sb = new StringBuilder("order: ");
        for (ListNode n = merged; n != null; n = n.next) sb.append(n.timestamp).append(' ');
        log.info(sb.toString().trim());
    }
}
